struct ceph_osd_op {
	__le16 op;
	__le32 flags;
	union {
		struct {
			__le64 offset;
			__le64 length;
			__le64 truncate_size;
			__le32 truncate_seq;
		} __attribute__((packed)) extent;
		struct {
			__le32 name_len;
			__le32 value_len;
			__u8 cmp_op;
			__u8 cmp_mode;
		} __attribute__((packed)) xattr;
		struct {
			__u8 class_len;
			__u8 method_len;
			__u8 argc;
			__le32 indata_len;
		} __attribute__((packed)) cls;
		struct {
			__le64 cookie;
			__le64 count;
		} pgls;
		struct {
			__le64 snapid;
		} snap;
		struct {
			__le64 cookie;
			__le64 ver;
			__u8 op;
			__le32 gen;
		} __attribute__((packed)) watch;
		struct {
			__le64 cookie;
		} notify;
		struct {
			__le64 unused;
			__le64 ver;
		} assert_ver;
		struct {
			__le64 offset;
			__le64 length;
			__le64 src_offset;
		} clonerange;
		struct {
			__le64 expected_object_size;
			__le64 expected_write_size;
			__le32 flags;
		} __attribute__((packed)) alloc_hint;
		struct {
			__le64 snapid;
			__le64 src_version;
			__u8 flags;
			__le32 src_fadvise_flags;
		} __attribute__((packed)) copy_from;
	};
	__le32 payload_len;
} __attribute__((packed));

struct ceph_osd_req_op {
	u16 op;
	u32 flags;
	u32 indata_len;
	u32 outdata_len;
	s32 rval;
	union {
		struct ceph_osd_data raw_data_in;
		struct {
			u64 offset;
			u64 length;
			u64 truncate_size;
			u32 truncate_seq;
			int sparse_ext_cnt;
			struct ceph_sparse_extent *sparse_ext;
			struct ceph_osd_data osd_data;
		} extent;
		struct {
			u32 name_len;
			u32 value_len;
			__u8 cmp_op;
			__u8 cmp_mode;
			struct ceph_osd_data osd_data;
		} xattr;
		struct {
			const char *class_name;
			const char *method_name;
			struct ceph_osd_data request_info;
			struct ceph_osd_data request_data;
			struct ceph_osd_data response_data;
			__u8 class_len;
			__u8 method_len;
			u32 indata_len;
		} cls;
		struct {
			u64 cookie;
			__u8 op;
			u32 gen;
		} watch;
		struct {
			struct ceph_osd_data request_data;
		} notify_ack;
		struct {
			u64 cookie;
			struct ceph_osd_data request_data;
			struct ceph_osd_data response_data;
		} notify;
		struct {
			struct ceph_osd_data response_data;
		} list_watchers;
		struct {
			u64 expected_object_size;
			u64 expected_write_size;
			u32 flags;
		} alloc_hint;
		struct {
			u64 snapid;
			u64 src_version;
			u8 flags;
			u32 src_fadvise_flags;
			struct ceph_osd_data osd_data;
		} copy_from;
		struct {
			u64 ver;
		} assert_ver;
	};
};

