struct mlx4_eqe {
	u8 reserved1;
	u8 type;
	u8 reserved2;
	u8 subtype;
	union {
		u32 raw[6];
		struct {
			__be32 cqn;
		} comp;
		struct {
			u16 reserved1;
			__be16 token;
			u32 reserved2;
			u8 reserved3[3];
			u8 status;
			__be64 out_param;
		} __attribute__((packed)) cmd;
		struct {
			__be32 qpn;
		} qp;
		struct {
			__be32 srqn;
		} srq;
		struct {
			__be32 cqn;
			u32 reserved1;
			u8 reserved2[3];
			u8 syndrome;
		} cq_err;
		struct {
			u32 reserved1[2];
			__be32 port;
		} port_change;
		struct {
			u32 reserved;
			u32 bit_vec[4];
		} comm_channel_arm;
		struct {
			u8 port;
			u8 reserved[3];
			__be64 mac;
		} __attribute__((packed)) mac_update;
		struct {
			__be32 slave_id;
		} flr_event;
		struct {
			__be16 current_temperature;
			__be16 warning_threshold;
		} warming;
		struct {
			u8 reserved[3];
			u8 port;
			union {
				struct {
					__be16 mstr_sm_lid;
					__be16 port_lid;
					__be32 changed_attr;
					u8 reserved[3];
					u8 mstr_sm_sl;
					__be64 gid_prefix;
				} __attribute__((packed)) port_info;
				struct {
					__be32 block_ptr;
					__be32 tbl_entries_mask;
				} tbl_change_info;
				struct {
					u8 sl2vl_table[8];
				} sl2vl_tbl_change_info;
			} params;
		} port_mgmt_change;
		struct {
			u8 reserved[3];
			u8 port;
			u32 reserved1[5];
		} bad_cable;
	} event;
	u8 slave_id;
	u8 reserved3[2];
	u8 owner;
};

